import { useEffect, useRef, useState, type ReactNode, type FormEvent } from 'react';
import { Activity, ArrowUpLeft, Bell, BookOpen, Box, ChevronLeft, ChevronRight, CircleHelp, Clock3,
  Cpu, Database, ExternalLink, Globe2, HardDrive, LayoutGrid, List, LoaderCircle, LockKeyhole, Menu,
  Network, Plus, Power, Radio, RefreshCw, Search, Server, Settings2, ShieldCheck, Smartphone, Trash2, X, Zap } from 'lucide-react';
import { ApiError, cancelJob, pollSnapshots, submitJob } from './api';
import ConnectionHelp from './ConnectionHelp';
import Diagnostics from './Diagnostics';
import SecurityPanel from './SecurityPanel';
import CatalogSetup, { applicationGuide } from './CatalogSetup';
import ArtifactPanel from './ArtifactPanel';
import { actionText, activeDevices, activeJob, deviceStatus, diagnoseCommand, egressText, eventText, fa, formatSize, formatTime, isSnapshotFresh,
  jobStateText, provisionableProxies, resumablePhases, runningContainer, screenPath, startablePhases, statusText, type Device, type DeviceStatus, type Job,
  type FarmEvent, type ProxyRecord, type Snapshot } from './domain';

type Page = 'devices' | 'sessions' | 'proxies' | 'backups' | 'events' | 'architecture' | 'settings';
const pages: { id: Page; title: string; icon: typeof Smartphone }[] = [
  { id: 'devices', title: 'دستگاه‌ها', icon: LayoutGrid }, { id: 'sessions', title: 'جلسات و صف', icon: Radio },
  { id: 'proxies', title: 'شبکه و پراکسی', icon: Network }, { id: 'backups', title: 'پشتیبان‌ها', icon: Database },
  { id: 'events', title: 'رویدادها', icon: Activity }, { id: 'architecture', title: 'معماری سیستم', icon: Box },
  { id: 'settings', title: 'تنظیمات فارم', icon: Settings2 },
];
const guide = 'https://github.com/mjpouladi/AndroidFarm/blob/main/docs/GUIDE.fa.md';
const phaseText: Record<string, string> = { reserved: 'رزرو شده', volume_created: 'فضای داده ساخته شد', secret_installed: 'شبکه پیکربندی شد',
  identity_baselining: 'ثبت وضعیت اولیه', starting: 'راه‌اندازی', installing_apk: 'نصب برنامه', ready_for_operator: 'آماده‌سازی تکمیل شده', failed: 'آماده‌سازی ناموفق' };
const containerText: Record<string, string> = { healthy: 'سالم', unhealthy: 'ناسالم', running: 'در حال اجرا', starting: 'در حال شروع',
  stopped: 'متوقف', missing: 'ساخته نشده', exited: 'خارج شده', created: 'ساخته شده', restarting: 'در حال بازراه‌اندازی' };
const message = (error: unknown) => error instanceof Error ? error.message : 'عملیات ناموفق بود.';
export function PreparationDiagnostics({ device }: { device: Pick<Device, 'id' | 'last_error' | 'failed_at'> }) {
  const command = diagnoseCommand(device.id);
  return <div>
    {device.last_error && <><p><strong>آخرین توقف ثبت‌شده:</strong> <span dir="ltr">{device.last_error}</span>
      {device.failed_at != null && <><br /><time dateTime={new Date(device.failed_at * 1000).toISOString()}>{formatTime(device.failed_at)}</time></>}</p>
      <p>این پیام مربوط به آخرین اجرای آماده‌سازی است؛ درخواست‌های ردشده پیش از اجرا ممکن است آن را تغییر ندهند.</p></>}
    {command && <><p>برای بررسی وضعیت فعلی و لاگ عملیات، این فرمان فقط‌خواندنی را روی میزبان اجرا کنید:</p>
      <pre className="job-result" dir="ltr" tabIndex={0} aria-label="فرمان بررسی دستگاه؛ قابل کپی" style={{ userSelect: 'all' }}><code>{command}</code></pre></>}
  </div>;
}
function Status({ status }: { status: DeviceStatus }) { return <span className={`status ${status}`}><i />{statusText[status]}</span>; }
function IconButton({ label, children, onClick }: { label: string; children: ReactNode; onClick: () => void }) {
  return <button className="icon-button" aria-label={label} title={label} onClick={onClick}>{children}</button>;
}
function Modal({ children, title, onClose, wide = false }: { children: ReactNode; title: string; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const dialog = ref.current!; dialog.showModal(); return () => dialog.close(); }, []);
  return <dialog className={wide ? 'modal wide' : 'modal'} ref={ref} aria-label={title} onCancel={onClose}
    onClick={e => { if (e.target === e.currentTarget) onClose(); }}><div className="modal-head"><h2>{title}</h2>
    <IconButton label="بستن" onClick={onClose}><X size={20} /></IconButton></div>{children}</dialog>;
}

export default function App() {
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const [connectionError, setConnectionError] = useState('');
  const [connectionStatus, setConnectionStatus] = useState<number | null>(null);
  const [now, setNow] = useState(Date.now());
  const [refresh, setRefresh] = useState(0);
  const [pending, setPending] = useState(false);
  const [awaitingSnapshot, setAwaitingSnapshot] = useState(false);
  const submitLock = useRef(false);
  const [page, setPage] = useState<Page>(() => pages.find(p => p.id === location.hash.slice(1))?.id ?? 'devices');
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all');
  const [view, setView] = useState<'grid' | 'list'>('grid');
  const [pageIndex, setPageIndex] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const [detailTab, setDetailTab] = useState('overview');
  const [screenRevision, setScreenRevision] = useState(0);
  const [addOpen, setAddOpen] = useState(false);
  const [proxyOpen, setProxyOpen] = useState(false);
  const [proxyDisable, setProxyDisable] = useState<ProxyRecord | null>(null);
  const [securityProxyId, setSecurityProxyId] = useState('');
  const [help, setHelp] = useState(false);
  const [confirm, setConfirm] = useState<Device | null>(null);
  const [releaseDevice, setReleaseDevice] = useState<Device | null>(null);
  const [releaseReviewed, setReleaseReviewed] = useState(false);
  const [removeDevice, setRemoveDevice] = useState<Device | null>(null);
  const [removeConfirm, setRemoveConfirm] = useState('');
  const [removePurge, setRemovePurge] = useState(false);
  const [navOpen, setNavOpen] = useState(false);
  const [toast, setToast] = useState('');
  const [phone, setPhone] = useState('');
  const [proxyId, setProxyId] = useState('');
  const [egress, setEgress] = useState<'proxy' | 'direct'>('proxy');
  const [artifactId, setArtifactId] = useState('');
  const [authorized, setAuthorized] = useState(false);
  const [formError, setFormError] = useState('');
  const [proxyForm, setProxyForm] = useState({ id: '', label: '', type: 'socks5', server: '', server_port: '', username: '', password: '', expected_egress_ip: '' });
  const [compact, setCompact] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);

  useEffect(() => pollSnapshots(data => { setSnapshot(data); setConnectionError(''); setConnectionStatus(null); setAwaitingSnapshot(false); }, error => { setConnectionError(message(error)); setConnectionStatus(error instanceof ApiError ? error.status : null); }), [refresh]);
  useEffect(() => { const timer = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(timer); }, []);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 7000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const handler = () => { setPage(pages.find(p => p.id === location.hash.slice(1))?.id ?? 'devices'); setQuery(''); setFilter('all'); setPageIndex(0); };
    window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, []);
  const fresh = !connectionError && isSnapshotFresh(snapshot, now);
  const canMutate = fresh && !pending && !awaitingSnapshot && !snapshot?.errors.some(error => ['configuration', 'queue'].includes(error.component));
  const devices = snapshot?.devices ?? [];
  const proxies = snapshot?.proxies ?? [];
  const jobs = snapshot?.jobs ?? [];
  const report = snapshot?.resources;
  const activeCount = activeDevices(devices);
  const waiting = jobs.filter(j => j.state === 'queued');
  const working = jobs.filter(j => j.state === 'running');
  const chosen = devices.find(d => d.id === selected);
  const chosenPath = chosen && screenPath(chosen);
  const chosenBusy = !!chosen && jobs.some(j => j.device === chosen.id && activeJob(j));
  const availableProxies = provisionableProxies(proxies, devices);
  // An incomplete preparation is resumed with the original request; a plain start is refused by the host.
  const chosenAssignedProxy = chosen ? availableProxies.find(proxy => proxy.assigned_device === chosen.id) : undefined;
  const chosenIncomplete = !!chosen && resumablePhases.includes(chosen.phase);
  const chosenCanResume = chosenIncomplete && (chosen?.egress === 'direct' || !!chosenAssignedProxy);
  const chosenStartable = !!chosen && startablePhases.includes(chosen.phase);
  const artifacts = snapshot?.artifacts.filter(a => a.available) ?? [];
  const warnings = snapshot?.errors ?? [];
  const unavailable = (component: string) => !snapshot || warnings.some(error => error.component === component || error.component === 'configuration');
  const canChangeDevice = canMutate && !['inventory', 'docker', 'holds'].some(unavailable);
  const countActive = ['inventory', 'docker'].some(unavailable) ? '—' : fa(activeCount);
  const problemDevices = devices.filter(d => deviceStatus(d, jobs) === 'error');
  const title = pages.find(p => p.id === page)!.title;
  const normalized = query.trim().toLowerCase().replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
  const filtered = devices.filter(d => `${d.id} ${d.phone ?? ''} ${d.proxy ?? ''}`.toLowerCase().includes(normalized) && (filter === 'all' || deviceStatus(d, jobs) === filter));
  const pageCount = Math.max(1, Math.ceil(filtered.length / 12));
  const visible = filtered.slice(pageIndex * 12, (pageIndex + 1) * 12);
  useEffect(() => { setPageIndex(current => Math.min(current, pageCount - 1)); }, [pageCount]);
  function navigate(next: Page) { setPage(next); location.hash = next; setQuery(''); setFilter('all'); setPageIndex(0); setNavOpen(false); window.scrollTo({ top: 0 }); }
  function openDevice(device: Device, tab = 'overview') { setSelected(device.id); setDetailTab(tab); }
  function closeRemove() { setRemoveDevice(null); setRemoveConfirm(''); setRemovePurge(false); }
  async function perform(action: string, device?: string, params?: Record<string, unknown>): Promise<boolean> {
    if (!canMutate || !snapshot || submitLock.current) return false;
    submitLock.current = true; setPending(true); setFormError('');
    try {
      const job = await submitJob({ action, ...(device ? { device } : {}), ...(params ? { params } : {}) }, snapshot.csrf_token);
      setToast(`درخواست ${actionText[action] ?? action} ثبت شد؛ وضعیت: ${jobStateText[job.state]}.`);
      setAwaitingSnapshot(true);
      setRefresh(n => n + 1);
      return true;
    } catch (error) { setFormError(message(error)); setToast(message(error)); return false; }
    finally { submitLock.current = false; setPending(false); }
  }
  async function cancel(job: Job) {
    if (!canMutate || !snapshot || submitLock.current || job.state !== 'queued') return;
    submitLock.current = true; setPending(true);
    try { const response = await cancelJob(job.id, snapshot.csrf_token); setToast(`وضعیت درخواست: ${jobStateText[response.state]}`); setAwaitingSnapshot(true); setRefresh(n => n + 1); }
    catch (error) { setToast(message(error)); }
    finally { submitLock.current = false; setPending(false); }
  }
  async function addDevice(event: FormEvent) {
    event.preventDefault();
    if (!/^\+[1-9]\d{9,14}$/.test(phone)) { setFormError('شماره را با + و کد کشور وارد کنید.'); return; }
    const direct = egress === 'direct';
    if (!authorized || (!direct && !availableProxies.some(p => p.id === proxyId)) || !artifacts.some(a => a.id === artifactId)) {
      setFormError(direct ? 'برنامهٔ تأییدشده و مجوز استفاده از شماره لازم است.' : 'پراکسی آزاد، برنامهٔ تأییدشده و مجوز استفاده از شماره لازم است.'); return;
    }
    // Direct egress never sends a proxy reference; the host validates the combination again.
    if (await perform('provision', undefined, { phone, owner_authorized: true, artifact_id: artifactId, egress, ...(direct ? {} : { proxy_id: proxyId }) })) {
      setAddOpen(false); setPhone(''); setAuthorized(false); setProxyId(''); setArtifactId(''); navigate('sessions');
    }
  }
  async function addProxy(event: FormEvent) {
    event.preventDefault();
    const params = { ...proxyForm, server_port: Number(proxyForm.server_port) };
    // Credentials exist only in this request and the server's private secret store.
    const request = perform('proxy-add', undefined, params);
    setProxyForm(current => ({ ...current, username: '', password: '' }));
    if (await request) { setProxyOpen(false); setProxyForm({ id: '', label: '', type: 'socks5', server: '', server_port: '', username: '', password: '', expected_egress_ip: '' }); }
  }
  function closeProxy() { setProxyOpen(false); setFormError(''); setProxyForm(current => ({ ...current, username: '', password: '' })); }
  function beginAdd() { setFormError(''); setEgress(availableProxies.length ? 'proxy' : 'direct'); setAddOpen(true); }
  const jobDetails = selectedJob && (jobs.find(j => j.id === selectedJob.id) ?? selectedJob);
  const resourcesText = report ? `${fa(report.cpu_cores)} هسته · ${fa(report.ram_gib)} GB حافظه` : 'گزارش منابع در دسترس نیست';

  return <div className={`app ${compact ? 'compact' : ''}`}>
    {navOpen && <button className="nav-overlay" aria-label="بستن منو" onClick={() => setNavOpen(false)} />}
    <aside className={`sidebar ${navOpen ? 'open' : ''}`}>
      <a className="brand" href="#devices" onClick={() => navigate('devices')}><div className="brand-mark"><i /><i /><i /><i /></div><span>Android Farm<small>کنسول عملیات</small></span></a>
      <div className="workspace"><span className="workspace-icon"><Server size={19} /></span><div>فارم اصلی<small>{fresh ? 'متصل به میزبان' : snapshot ? 'اتصال نیاز به بررسی دارد' : 'در انتظار اتصال'}</small></div><span className={`live-dot ${fresh ? '' : 'offline-dot'}`} /></div>
      <p className="nav-label">فضای کاری</p><nav>{pages.slice(0, 5).map(({ id, title, icon: Icon }) => <button key={id} className={page === id ? 'active' : ''} onClick={() => navigate(id)}><Icon size={20} /><span>{title}</span>{id === 'devices' && <b>{snapshot ? fa(devices.length) : '—'}</b>}{id === 'sessions' && waiting.length > 0 && <b>{fa(waiting.length)}</b>}</button>)}</nav>
      <p className="nav-label second">مدیریت</p><nav>{pages.slice(5).map(({ id, title, icon: Icon }) => <button key={id} className={page === id ? 'active' : ''} onClick={() => navigate(id)}><Icon size={20} /><span>{title}</span></button>)}</nav>
      <div className="sidebar-bottom"><div className="host-card"><div><span className={`live-dot ${fresh ? '' : 'offline-dot'}`} /><b>منابع میزبان</b><span className="host-tag">{fresh ? 'LIVE' : 'OFFLINE'}</span></div><p>{resourcesText}</p><div className="host-meter"><i style={{ width: `${Math.min(100, report?.active_capacity ? activeCount / report.active_capacity * 100 : 0)}%` }} /></div><small>{report ? `ظرفیت فعال: ${fa(report.active_capacity)} دستگاه` : 'مقادیر پس از اتصال نمایش داده می‌شوند'}</small></div>
        <button className="help-button" onClick={() => setHelp(true)}><CircleHelp size={19} />راهنمای عملیات<ArrowUpLeft size={16} /></button>
        <div className="profile"><div className="avatar">ک</div><div>کنسول مدیریت<small>دسترسی حفاظت‌شدهٔ فارم</small></div><LockKeyhole size={14} /></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="mobile-menu icon-button" aria-label="منو" onClick={() => setNavOpen(true)}><Menu size={22} /></button><span>فضای کاری</span><ChevronLeft size={15} /><strong>{title}</strong></div>
      <div className="topbar-left"><span className={`connection-pill ${fresh ? 'connected' : 'disconnected'}`}><span />{fresh ? 'وضعیت زندهٔ میزبان' : 'اتصال زنده برقرار نیست'}</span><IconButton label="به‌روزرسانی وضعیت" onClick={() => setRefresh(n => n + 1)}><RefreshCw size={17} /></IconButton><IconButton label="رویدادهای عملیات" onClick={() => navigate('events')}><Bell size={18} /></IconButton></div></header>
      <main>
        {!fresh && <div className="connection-banner" role="alert"><Activity size={21} /><div><strong>{connectionError ? 'ارتباط با سرویس کنترل برقرار نیست' : snapshot ? 'وضعیت دریافت‌شده قدیمی است' : 'در حال دریافت وضعیت واقعی میزبان'}</strong><p>{connectionError || (snapshot ? 'تا دریافت وضعیت تازه، عملیات غیرفعال است؛ مقادیر زیر آخرین گزارش دریافت‌شده‌اند.' : 'در صورت ادامهٔ انتظار، استقرار سرویس API و مسیر /api/ را بررسی کنید.')}</p>{snapshot && <small>آخرین گزارش: {formatTime(snapshot.collected_at)}</small>}</div><button className="secondary small" onClick={() => setRefresh(n => n + 1)}>تلاش دوباره</button></div>}
        {!fresh && connectionError && <ConnectionHelp status={connectionStatus} retry={() => setRefresh(n => n + 1)} />}
        {warnings.length > 0 && <div className="component-warnings" role="status">{warnings.map((warning, index) => <p key={`${warning.component}-${index}`}><b>{warning.component}:</b> {warning.message}</p>)}</div>}
        {(page === 'devices' || page === 'settings') && <CatalogSetup snapshot={snapshot} fresh={fresh} />}
        {page === 'settings' && <ArtifactPanel snapshot={snapshot} csrf={snapshot?.csrf_token ?? ''} canMutate={canMutate}
          onJob={job => { setToast(`درخواست ${actionText[job.action] ?? job.action} ثبت شد؛ وضعیت: ${jobStateText[job.state]}.`); setAwaitingSnapshot(true); setRefresh(n => n + 1); }}
          onError={text => setToast(text)} />}
        <div className="page-heading"><div><div className="eyebrow">ANDROID FARM <span>/</span> OPERATIONS</div><h1>{page === 'devices' ? 'همهٔ دستگاه‌ها، یک فضای کار.' : title}</h1><p>{({ devices: 'دستگاه‌های واقعی میزبان، وضعیت جاری و عملیات قابل پیگیری.', sessions: 'درخواست‌های ثبت‌شده و اجرای واقعی آن‌ها روی میزبان.', proxies: 'اتصال‌های ثبت‌شده، تخصیص اختصاصی و نتیجهٔ آزمون خروجی.', backups: 'آرشیوهای موجود روی سرور و زمان ثبت آن‌ها.', events: 'تاریخچهٔ پایدار عملیات و نتیجهٔ هر درخواست.', architecture: 'مسیر واقعی فرمان، داده و کنترل صفحه در پلتفرم.', settings: 'پیکربندی فعال و ظرفیت اندازه‌گیری‌شدهٔ میزبان.' })[page]}</p></div>
          {page === 'devices' ? <button className="primary" disabled={!canMutate} onClick={beginAdd}><Plus size={18} />افزودن دستگاه</button> : page === 'proxies' ? <button className="primary" disabled={!canMutate} onClick={() => { setFormError(''); setProxyOpen(true); }}><Plus size={18} />ثبت پراکسی</button> : snapshot && <span className="section-chip"><Clock3 size={13} />{formatTime(snapshot.collected_at)}</span>}</div>

        {page === 'devices' && <>
          <section className="capacity-panel"><div className="capacity-title"><div className="capacity-icon"><Zap size={23} /></div><div><h2>ظرفیت واقعی، مصرف کنترل‌شده</h2><p>{resourcesText}</p><p>{report ? `حافظهٔ آزاد: ${fa(report.available_ram_gib)} GB · دیسک آزاد: ${fa(report.disk_free_gib)} GB` : 'منبعی تخمین زده نمی‌شود؛ گزارش میزبان لازم است.'}</p></div></div>
            <div className="slots-wrap"><div className="slots-label"><b>{countActive} <span>روشن / ظرفیت {report ? fa(report.active_capacity) : '—'}</span></b><span>افزودنی با دیسک فعلی: {report?.catalog_capacity != null ? fa(report.catalog_capacity) : '—'}</span></div><div className="capacity-track"><i style={{ width: `${Math.min(100, report?.active_capacity ? activeCount / report.active_capacity * 100 : 0)}%` }} /></div></div></section>
          <section className="stats-grid"><Stat icon={<Smartphone />} label="دستگاه‌های ثبت‌شده" value={unavailable('inventory') ? '—' : fa(devices.length)} note="بر اساس موجودی میزبان" />
            <Stat icon={<Radio />} label="سرویس کنترل سالم" value={['inventory', 'docker', 'holds'].some(unavailable) ? '—' : fa(devices.filter(d => d.screen_ready).length)} note="سلامت سرویس؛ تصویر در جلسه بررسی می‌شود" />
            <Stat icon={<Clock3 />} label="عملیات در انتظار" value={unavailable('queue') ? '—' : fa(waiting.length)} note={unavailable('queue') ? 'صف در دسترس نیست' : `${fa(working.length)} عملیات در حال اجرا`} />
            <Stat icon={<Activity />} label="دستگاه نیازمند بررسی" value={unavailable('inventory') ? '—' : fa(problemDevices.length)} note="خطای کانتینر یا توقف حفاظتی" /></section>
          <section className="fleet-section"><div className="section-header"><div className="section-title"><h2>ناوگان دستگاه‌ها</h2><span>{snapshot ? fa(devices.length) : '—'} دستگاه</span></div><div className="view-toggle"><button className={view === 'grid' ? 'active' : ''} aria-label="نمای کارت" aria-pressed={view === 'grid'} onClick={() => setView('grid')}><LayoutGrid size={17} /></button><button className={view === 'list' ? 'active' : ''} aria-label="نمای جدول" aria-pressed={view === 'list'} onClick={() => setView('list')}><List size={18} /></button></div></div>
            <div className="toolbar"><div className="filter-tabs">{[['all', 'همه'], ['running', 'روشن'], ['off', 'خاموش'], ['error', 'نیاز به بررسی'], ['queued', 'در صف']].map(([id, label]) => <button key={id} className={filter === id ? 'selected' : ''} onClick={() => { setFilter(id); setPageIndex(0); }}>{label}</button>)}</div><SearchField query={query} onChange={value => { setQuery(value); setPageIndex(0); }} /></div>
            {!visible.length ? <Empty title={unavailable('inventory') ? 'موجودی میزبان در دسترس نیست' : devices.length ? 'دستگاهی پیدا نشد' : 'اولین دستگاه را آماده کنید'} text={unavailable('inventory') ? 'تا دریافت پاسخ معتبر، نمی‌توان خالی‌بودن فهرست دستگاه‌ها را تأیید کرد؛ پیام اتصال یا خطای بخش موجودی را بررسی کنید.' : devices.length ? 'جست‌وجو یا فیلتر را تغییر دهید.' : 'ابتدا یک پراکسی ثبت کنید و برنامهٔ تأییدشده را به فهرست نصب میزبان اضافه کنید؛ سپس دستگاه بسازید.'} /> : view === 'grid' ? <div className="device-grid">{visible.map(device => {
              const status = deviceStatus(device, jobs); const busy = jobs.some(job => job.device === device.id && activeJob(job));
              return <article className={`device-card ${status === 'running' ? 'is-running' : ''}`} key={device.id}><div className="device-top"><div className={`device-symbol ${status}`}><Smartphone size={23} /></div><div className="device-name"><button onClick={() => openDevice(device)}><b dir="ltr">{device.id}</b><ArrowUpLeft size={13} /></button><span>{phaseText[device.phase] ?? device.phase}</span></div><IconButton label={`جزئیات ${device.id}`} onClick={() => openDevice(device)}><Settings2 size={18} /></IconButton></div>
                <div className="device-phone"><span>شمارهٔ اختصاصی</span><b dir="ltr">{device.phone || '—'}</b></div><div className="device-network"><Network size={14} /><span dir="ltr" className="truncate">{egressText(device)}</span></div>
                <div className="device-live-metrics"><span>CPU <b dir="ltr">{device.cpu || '—'}</b></span><span>RAM <b dir="ltr">{device.memory || '—'}</b></span></div>
                <div className="device-footer"><Status status={status} />{device.screen_ready ? <button className="device-action running-action" disabled={!fresh} onClick={() => openDevice(device, 'screen')}><ArrowUpLeft size={15} />کنترل صفحه</button> : runningContainer(device.containers.android) || busy ? <button className="device-action" onClick={() => openDevice(device)}>بررسی وضعیت</button> : <button className="device-action" disabled={!canChangeDevice || !!device.hold} onClick={() => void perform('up', device.id)}><Power size={14} />روشن کردن</button>}</div></article>;
            })}</div> : <div className="table-wrap panel"><table><thead><tr><th>دستگاه</th><th>شماره</th><th>وضعیت</th><th>CPU / حافظه</th><th>شبکه</th></tr></thead><tbody>{visible.map(device => <tr key={device.id}><td><button className="text-button mono" onClick={() => openDevice(device)}>{device.id}</button></td><td dir="ltr">{device.phone || '—'}</td><td><Status status={deviceStatus(device, jobs)} /></td><td dir="ltr">{device.cpu || '—'}<small>{device.memory || '—'}</small></td><td dir="ltr">{egressText(device)}</td></tr>)}</tbody></table></div>}
            <div className="pagination"><span>نمایش {fa(filtered.length ? pageIndex * 12 + 1 : 0)} تا {fa(Math.min((pageIndex + 1) * 12, filtered.length))} از {fa(filtered.length)}</span><div><button aria-label="صفحهٔ قبل" disabled={pageIndex === 0} onClick={() => setPageIndex(n => n - 1)}><ChevronRight size={16} /></button><span>{fa(pageIndex + 1)} / {fa(pageCount)}</span><button aria-label="صفحهٔ بعد" disabled={pageIndex + 1 >= pageCount} onClick={() => setPageIndex(n => n + 1)}><ChevronLeft size={16} /></button></div></div>
          </section>
        </>}

        {page === 'sessions' && <><div className="sessions-banner"><div><Radio size={27} /><h2>{countActive} دستگاه روشن</h2><p>ثبت درخواست به معنی موفقیت عملیات نیست؛ نتیجه پس از اجرای میزبان ثبت می‌شود.</p></div><div className="capacity-number">{countActive}<span> / {report ? fa(report.active_capacity) : '—'}</span></div></div><section className="panel"><div className="section-header"><h2>صف عملیات کنترل</h2><span className="tag">{unavailable('queue') ? 'صف در دسترس نیست' : `${fa(waiting.length)} منتظر · ${fa(working.length)} در حال اجرا`}</span></div><JobList jobs={jobs.filter(activeJob)} onOpen={setSelectedJob} onCancel={cancel} canMutate={canMutate} unavailable={unavailable('queue')} /></section><section className="panel secondary-panel"><h2>جلسه‌های روشن</h2>{devices.filter(d => runningContainer(d.containers.android)).map(device => <div className="session-row" key={device.id}><Smartphone size={22} /><div><b dir="ltr">{device.id}</b><p>{device.phone || '—'}</p></div><Status status={deviceStatus(device, jobs)} /><button className="secondary small" onClick={() => openDevice(device, 'screen')}>کنترل صفحه</button><button className="danger small" disabled={!canChangeDevice || jobs.some(j => j.device === device.id && activeJob(j))} onClick={() => setConfirm(device)}>خاموش کردن</button></div>)}{activeCount === 0 && <Empty title={['inventory', 'docker'].some(unavailable) ? 'وضعیت جلسه‌ها در دسترس نیست' : 'دستگاه روشنی گزارش نشده'} text={['inventory', 'docker'].some(unavailable) ? 'برای تأیید جلسه‌های روشن، پاسخ معتبر میزبان لازم است.' : 'پس از راه‌اندازی موفق، جلسهٔ دستگاه اینجا ظاهر می‌شود.'} />}</section></>}

        {page === 'proxies' && <><div className="notice"><ShieldCheck size={23} /><div><strong>اتصال واقعی، نتیجهٔ قابل بررسی</strong><p>فعال‌بودن اتصال به معنی سلامت آن نیست. نتیجهٔ آخرین آزمون و IP مشاهده‌شده جداگانه نمایش داده می‌شوند. اطلاعات ورود فقط هنگام ثبت ارسال می‌شوند.</p></div></div>{proxies.length ? <div className="panel table-wrap"><table><thead><tr><th>اتصال</th><th>نشانی</th><th>تخصیص</th><th>آخرین آزمون</th><th>عملیات</th></tr></thead><tbody>{proxies.map(proxy => <tr key={proxy.id}><td><strong>{proxy.label}</strong><small dir="ltr">{proxy.id} · {proxy.type.toUpperCase()}</small><small>{proxy.state === 'enabled' ? 'فعال' : 'غیرفعال'}</small></td><td dir="ltr">{proxy.server}:{proxy.server_port}<small>IP: {proxy.expected_egress_ip}</small></td><td dir="ltr">{proxy.assigned_device ?? '—'}</td><td><ProxyHealth proxy={proxy} />{proxy.last_health && <small>{formatTime(proxy.last_health.checked_at)}</small>}</td><td><div className="table-actions"><button className="secondary small" disabled={!fresh} onClick={() => { setSecurityProxyId(proxy.id); navigate('settings'); }}>مدیریت رمز</button><button className="secondary small" disabled={!canMutate || proxy.state !== 'enabled'} onClick={() => void perform('proxy-test', undefined, { id: proxy.id })}>تست خروجی</button><button className="secondary small" disabled={!canMutate} onClick={() => proxy.state === 'enabled' ? setProxyDisable(proxy) : void perform('proxy-enable', undefined, { id: proxy.id })}>{proxy.state === 'enabled' ? 'غیرفعال' : 'فعال'}</button></div></td></tr>)}</tbody></table></div> : <Empty title={unavailable('proxies') ? 'رجیستری پراکسی در دسترس نیست' : 'پراکسی ثبت نشده است'} text={unavailable('proxies') ? 'خطای رجیستری یا اتصال میزبان را بررسی کنید؛ خالی‌بودن فهرست هنوز تأیید نشده است.' : 'نشانی سرویس خریداری‌شده، اطلاعات ورود و IP خروجی ثابت را با دکمهٔ ثبت پراکسی وارد کنید.'} />}</>}

        {page === 'backups' && <><div className="notice"><Database size={24} /><div><strong>بکاپ سازگار با دادهٔ دستگاه</strong><p>از جزئیات دستگاه خاموش، پشتیبان‌گیری را شروع کنید. این فهرست فقط آرشیوهای موجود روی میزبان را نشان می‌دهد. بازیابی فعلاً از راهنمای عملیات انجام می‌شود.</p></div></div>{snapshot?.backups.length ? <div className="panel table-wrap"><table><thead><tr><th>آرشیو</th><th>دستگاه</th><th>زمان ثبت</th><th>اندازه</th></tr></thead><tbody>{snapshot.backups.map(backup => <tr key={backup.id}><td className="mono">{backup.id}</td><td><button className="text-button mono" onClick={() => { setSelected(backup.device); setDetailTab('overview'); }}>{backup.device}</button></td><td>{formatTime(backup.created_at)}</td><td dir="ltr">{formatSize(backup.size_bytes)}</td></tr>)}</tbody></table></div> : <Empty title={unavailable('backups') ? 'فهرست بکاپ در دسترس نیست' : 'آرشیوی گزارش نشده است'} text={unavailable('backups') ? 'خطای دسترسی به فهرست بکاپ را بررسی کنید؛ این وضعیت به معنی حذف آرشیوها نیست.' : 'پس از پایان موفق پشتیبان‌گیری، آرشیو واقعی در این فهرست نمایش داده می‌شود.'} />}</>}

        {page === 'events' && <section className="panel"><div className="section-header"><h2>تاریخچهٔ درخواست‌ها</h2><span className="tag">{unavailable('queue') ? 'تاریخچه در دسترس نیست' : `${fa(jobs.length)} رکورد دریافت‌شده`}</span></div><JobList jobs={jobs} onOpen={setSelectedJob} onCancel={cancel} canMutate={canMutate} unavailable={unavailable('queue')} /><div className="section-header"><h2>رویدادهای دستگاه‌ها</h2><span className="tag">{unavailable('events') ? 'در دسترس نیست' : `${fa((snapshot?.events ?? []).length)} رویداد اخیر`}</span></div><EventList events={snapshot?.events ?? []} /></section>}

        {page === 'architecture' && <><div className="architecture-hero"><div><div className="eyebrow">LIVE CONTROL PLANE</div><h2>از کنسول تا دستگاه،<br />یک مسیر قابل پیگیری.</h2><p>کنسول وضعیت را از میزبان می‌خواند. هر تغییر یک درخواست پایدار با نتیجهٔ مشخص دارد؛ تصویر دستگاه مستقیماً از سرویس کنترل همان دستگاه دریافت می‌شود.</p></div><div className="arch-emblem"><Server size={70} strokeWidth={1} /><span>API · صف · Android</span></div></div><div className="architecture-flow">{[
          [Globe2, 'مرورگر', 'کنسول و scrcpy در همان دامنه'], [LockKeyhole, 'احراز هویت', 'Basic Auth مشترک در ورودی'], [Server, 'API میزبان', 'سوکت Unix داخلی و فرمان‌های مجاز'], [Clock3, 'اجرای پایدار', 'ثبت درخواست، وضعیت و نتیجه'], [Smartphone, 'دستگاه', 'Android، مسیر شبکه و دادهٔ مستقل'],
        ].map(([Icon, name, description], index) => { const NodeIcon = Icon as typeof Server; return <div className="flow-node" key={index}><span>0{index + 1}</span><NodeIcon size={29} /><h3>{name as string}</h3><p>{description as string}</p></div>; })}</div><div className="two-columns"><section className="panel architecture-panel"><h2><ShieldCheck size={20} />مرز کنترل و شبکه</h2><ul><li>API روی میزبان از سوکت Unix استفاده می‌کند؛ Docker Socket در مرورگر یا پورت عمومی قرار نمی‌گیرد.</li><li>فرمان‌ها پس از بررسی ورودی، مجوز و ظرفیت میزبان اجرا می‌شوند.</li><li>Redroid از فضای شبکهٔ اختصاصی دستگاه و دادهٔ پایدار خودش استفاده می‌کند.</li><li>رازهای پراکسی از پاسخ API و جدول‌های کنسول حذف می‌شوند.</li></ul></section><section className="panel architecture-panel"><h2><Activity size={20} />وضعیت و عملیات</h2><ul><li>موجودی، CPU و حافظه از Docker و گزارش میزبان دریافت می‌شوند.</li><li>صف کنسول تاریخچهٔ عملیات را نگه می‌دارد؛ عامل‌های Redis میزبان وظایف عملیاتی خود را مستقل انجام می‌دهند.</li><li>مشکل ارتباط، وضعیت قدیمی و خطای هر بخش آشکار نمایش داده می‌شود.</li><li>کنترل صفحه از مسیر همان دستگاه و WebSocket برقرار می‌شود؛ سلامت سرویس به‌تنهایی دریافت تصویر را تضمین نمی‌کند.</li></ul></section></div></>}

        {page === 'settings' && <><Diagnostics snapshot={snapshot} fresh={fresh} canMutate={canMutate} onActivate={() => void perform('core-activate', undefined, {})} /><SecurityPanel settings={snapshot?.settings.security} proxies={proxies} canMutate={canMutate} initialProxyId={securityProxyId} operationError={formError} onSubmit={perform} onJobs={() => navigate('sessions')} /><div className="settings-layout"><section className="panel"><h2>پیکربندی فعال</h2><Setting title="آدرس کنسول" note="از تنظیمات واقعی میزبان" value={snapshot?.settings.console_url || '—'} /><Setting title="شیوهٔ دسترسی" note="احراز هویت در ورودی و API بررسی می‌شود" value={snapshot?.settings.access_mode || '—'} /><Setting title="ظرفیت همزمان" note="کنترل نهایی پیش از روشن‌کردن روی سرور انجام می‌شود" value={report ? `${fa(report.active_capacity)} دستگاه` : '—'} /><Setting title="ظرفیت افزودهٔ ذخیره‌سازی" note="بر اساس فضای داده و منابع قابل استفاده" value={report?.catalog_capacity != null ? `${fa(report.catalog_capacity)} دستگاه` : '—'} /><Setting title="آخرین اندازه‌گیری منابع" note="زمان گزارش میزبان" value={report ? formatTime(report.collected_at) : '—'} /><Setting title="برنامه‌های آمادهٔ نصب" note="فایل باید روی میزبان موجود و در فهرست مورد اعتماد ثبت شده باشد" value={snapshot ? fa(artifacts.length) : '—'} /></section><aside className="panel settings-side"><h2>نمایش و راهنما</h2><label className="toggle-row"><span>کارت‌های فشرده</span><input type="checkbox" checked={compact} onChange={event => setCompact(event.target.checked)} /></label><p>این گزینه فقط نمایش همین صفحه را تغییر می‌دهد.</p><hr /><h3>تنظیمات استقرار</h3><p>تنظیمات امنیت، منابع و فهرست APK در میزبان نگهداری می‌شوند. تغییرشان از مسیر نصب و راهنمای واحد انجام می‌شود.</p><a className="secondary inline" href={guide} target="_blank" rel="noreferrer"><BookOpen size={16} />راهنمای واحد</a></aside></div></>}
      </main><footer className="app-footer"><span>ANDROID FARM / OPERATIONS</span><span>{snapshot ? `آخرین گزارش: ${formatTime(snapshot.collected_at)}` : 'در انتظار پاسخ میزبان'}</span><span><LockKeyhole size={12} />عملیات ثبت‌شده و قابل پیگیری</span></footer>
    </div>

    {chosen && <Modal title={`دستگاه ${chosen.id}`} wide onClose={() => setSelected(null)}><div className="detail-heading"><div className={`device-symbol ${deviceStatus(chosen, jobs)}`}><Smartphone size={27} /></div><div><h3>{phaseText[chosen.phase] ?? chosen.phase}</h3><p dir="ltr">{chosen.phone || '—'}</p></div><Status status={deviceStatus(chosen, jobs)} /></div><div className="detail-tabs">{[['overview', 'نمای کلی'], ['screen', 'کنترل زنده'], ['events', 'عملیات دستگاه']].map(([id, text]) => <button key={id} className={detailTab === id ? 'selected' : ''} onClick={() => setDetailTab(id)}>{text}</button>)}</div>
      {detailTab === 'overview' && <div className="detail-body"><div className="detail-metrics"><div><Cpu size={19} /><span>CPU اندروید</span><b dir="ltr">{chosen.cpu || '—'}</b></div><div><HardDrive size={19} /><span>حافظهٔ اندروید</span><b className="memory-value" dir="ltr">{chosen.memory || '—'}</b></div><div><Globe2 size={19} /><span>IP مورد انتظار</span><b className="ip-value" dir="ltr">{chosen.expected_egress_ip || '—'}</b></div></div><dl className="detail-list">{(['android', 'proxy', 'screen'] as const).map(role => <div key={role}><dt>{({ android: 'اندروید', proxy: 'شبکه', screen: 'کنترل صفحه' })[role]}</dt><dd>{containerText[chosen.containers[role]] ?? chosen.containers[role]}</dd></div>)}<div><dt>مسیر خروجی</dt><dd dir="ltr">{egressText(chosen)}</dd></div><div><dt>نشانی داخلی ADB</dt><dd dir="ltr">{chosen.adb || '—'}</dd></div><div><dt>آخرین پشتیبان</dt><dd>{snapshot?.backups.find(b => b.device === chosen.id) ? formatTime(snapshot.backups.find(b => b.device === chosen.id)!.created_at) : 'آرشیوی گزارش نشده'}</dd></div></dl>{chosen.hold && <div className="component-warnings"><strong>توقف حفاظتی فعال است</strong><p>{chosen.hold.reason || 'علت را در میزبان بررسی کنید.'}</p><p>پس از رفع علت، توقف حفاظتی باید توسط اپراتور در میزبان بررسی شود.</p></div>}<div className="notice compact-notice"><ShieldCheck size={18} /><p>خاموش‌کردن، دادهٔ پایدار دستگاه را حفظ می‌کند. CPU و حافظه مربوط به کانتینر اندروید هستند.</p></div></div>}
      {detailTab === 'screen' && <div className="live-screen-panel">{fresh && chosen.screen_ready && chosenPath ? <><div className="screen-toolbar"><span><Radio size={16} />سرویس کنترل آمادهٔ اتصال است</span><button className="secondary small" onClick={() => setScreenRevision(n => n + 1)}><RefreshCw size={14} />اتصال دوباره</button><a className="secondary small inline" href={chosenPath} target="_blank" rel="noreferrer"><ExternalLink size={14} />باز کردن مستقل</a></div><iframe key={`${chosen.id}-${screenRevision}`} className="live-screen-frame" src={chosenPath} title={`کنترل زندهٔ ${chosen.id}`} allow="fullscreen; clipboard-read; clipboard-write" /><p className="field-hint">تصویر و کنترل از scrcpy دریافت می‌شوند. اگر تصویر ظاهر نشد، مسیر مستقل را باز کنید و نتیجهٔ «بررسی ADB» را ببینید.</p></> : <Empty title={!fresh ? 'برای کنترل، اتصال تازه لازم است' : 'سرویس کنترل هنوز سالم گزارش نشده'} text={!fresh ? 'پس از بازیابی ارتباط میزبان می‌توانید جلسه را باز کنید.' : 'دستگاه را روشن کنید؛ سپس وضعیت اندروید، سرویس صفحه و نتیجهٔ بررسی ADB را مشاهده کنید.'} />}</div>}
      {detailTab === 'events' && <div className="detail-body"><JobList jobs={jobs.filter(job => job.device === chosen.id)} onOpen={setSelectedJob} onCancel={cancel} canMutate={canMutate} unavailable={unavailable('queue')} /></div>}
      <div className="modal-footer"><button className="secondary" disabled={!canChangeDevice || chosenBusy || !runningContainer(chosen.containers.android)} onClick={() => void perform('check', chosen.id)}>بررسی ADB</button><button className="secondary" disabled={!canChangeDevice || chosenBusy || !runningContainer(chosen.containers.android)} onClick={() => void perform('check-ip', chosen.id)}>بررسی IP</button><button className="secondary" disabled={!canChangeDevice || chosenBusy || !['stopped', 'exited', 'created', 'missing'].includes(chosen.containers.android)} onClick={() => void perform('backup', chosen.id)}><Database size={15} />بکاپ</button><span className="spacer" />{runningContainer(chosen.containers.android) ? <><button className="secondary" disabled={!canChangeDevice || chosenBusy || !!chosen.hold} onClick={() => void perform('restart', chosen.id)}><RefreshCw size={15} />راه‌اندازی مجدد</button><button className="danger" disabled={!canChangeDevice || chosenBusy} onClick={() => setConfirm(chosen)}><Power size={15} />خاموش کردن</button></> :<button className="primary" disabled={!canChangeDevice || chosenBusy || !!chosen.hold || !chosenStartable} title={chosenStartable ? undefined : 'آماده‌سازی این دستگاه ناتمام است؛ از «ادامهٔ آماده‌سازی» استفاده کنید'} onClick={() => void perform('up', chosen.id)}><Power size={15} />روشن کردن</button>}</div>
      {chosen.hold && <div className="hold-actions"><button className="secondary" disabled={!canChangeDevice || chosenBusy} onClick={() => { setReleaseReviewed(false); setReleaseDevice(chosen); }}><ShieldCheck size={16} />رفع توقف پس از بررسی</button><p>این فرمان دستگاه را خودکار روشن نمی‌کند.</p></div>}
      {chosenIncomplete && <div className="hold-actions"><button className="secondary" disabled={!canMutate || chosenBusy || !chosenCanResume} onClick={() => { setEgress(chosenAssignedProxy ? 'proxy' : 'direct'); setProxyId(chosenAssignedProxy ? chosenAssignedProxy.id : ''); setPhone(''); setArtifactId(''); setAuthorized(false); setFormError(''); setSelected(null); setAddOpen(true); }}><RefreshCw size={16} />ادامهٔ آماده‌سازی</button><p>{chosenCanResume ? 'آماده‌سازی این دستگاه ناتمام است و «روشن کردن» ساده آن را کامل نمی‌کند؛ شماره و برنامهٔ درخواست اولیه باید دوباره تأیید شوند.' : 'آماده‌سازی ناتمام است ولی پراکسی اختصاص‌یافته فعال یا موجود نیست؛ آن را در «شبکه و پراکسی» فعال کنید یا دستگاه را حذف کنید.'}</p><PreparationDiagnostics device={chosen} /></div>}
      <div className="hold-actions"><button className="danger" disabled={!canChangeDevice || chosenBusy} onClick={() => { setRemoveConfirm(''); setRemovePurge(false); setRemoveDevice(chosen); }}><Trash2 size={16} />حذف دستگاه از فارم</button><p>دستگاه متوقف، پراکسی آزاد و شناسه از موجودی حذف می‌شود؛ پاک‌کردن دادهٔ پایدار جداگانه تأیید می‌شود.</p></div>
    </Modal>}

    {proxyDisable && <Modal title="غیرفعال‌کردن اتصال پراکسی" onClose={() => setProxyDisable(null)}><div className="confirm-body"><div className="confirm-icon"><Network size={27} /></div><h3>{proxyDisable.label}</h3><p>{proxyDisable.assigned_device ? `دستگاه ${proxyDisable.assigned_device} متوقف می‌شود و توقف حفاظتی نگهداری برای آن ثبت می‌شود.` : 'این اتصال تا زمان فعال‌کردن دوباره، قابل استفاده نخواهد بود.'}</p><p>فعال‌کردن دوبارهٔ پراکسی، توقف حفاظتی را رفع نمی‌کند و دستگاه را روشن نمی‌کند.</p><div className="form-actions"><button className="secondary" onClick={() => setProxyDisable(null)}>انصراف</button><button className="danger" disabled={!canMutate} onClick={async () => { if (await perform('proxy-disable', undefined, { id: proxyDisable.id })) setProxyDisable(null); }}>ثبت غیرفعال‌سازی</button></div></div></Modal>}

    {releaseDevice && <Modal title="بررسی و رفع توقف حفاظتی" onClose={() => setReleaseDevice(null)}><form className="device-form" onSubmit={async event => { event.preventDefault(); if (releaseReviewed && await perform('release', releaseDevice.id, { review_completed: true })) setReleaseDevice(null); }}><p>دستگاه <b dir="ltr">{releaseDevice.id}</b> به علت <b>{releaseDevice.hold?.reason || 'ثبت‌شده در میزبان'}</b> متوقف شده است. وضعیت شبکه، مالکیت شماره و علت توقف را پیش از ادامه بررسی کنید.</p><label className="checkbox-label"><input type="checkbox" required checked={releaseReviewed} onChange={event => setReleaseReviewed(event.target.checked)} /><span>علت توقف را بررسی و برطرف کرده‌ام؛ درخواست رفع توقف را تأیید می‌کنم.</span></label><p className="field-hint">پس از موفقیت، روشن‌کردن دستگاه درخواست جداگانه‌ای است.</p><div className="form-actions"><button type="button" className="secondary" onClick={() => setReleaseDevice(null)}>انصراف</button><button className="primary" disabled={!canMutate || !releaseReviewed}>ثبت رفع توقف</button></div></form></Modal>}

    {addOpen && <Modal title="آماده‌سازی یا ادامهٔ نصب دستگاه" onClose={() => { setAddOpen(false); setPhone(''); }}><form className="device-form" onSubmit={addDevice}><div className="form-info"><span className="round-icon"><Smartphone size={24} /></span><div><strong>ایجاد روی میزبان</strong><p>شناسهٔ جدید را سرور تخصیص می‌دهد؛ ادامهٔ نصب، همان دستگاه را تکمیل می‌کند.</p></div></div><label>شمارهٔ متعلق به شما (برای ادامه، شمارهٔ درخواست اول)<input autoFocus value={phone} onChange={event => setPhone(event.target.value)} placeholder="+989…" dir="ltr" inputMode="tel" autoComplete="off" maxLength={16} required /></label><label>مسیر خروجی شبکه<select value={egress} onChange={event => { setEgress(event.target.value === 'direct' ? 'direct' : 'proxy'); if (event.target.value === 'direct') setProxyId(''); }}><option value="proxy">پراکسی اختصاصی با IP ثابت</option><option value="direct">بدون پراکسی — خروجی مستقیم میزبان</option></select></label>{egress === 'proxy' ? <><label>پراکسی آزاد یا نصب ناتمام<select value={proxyId} onChange={event => setProxyId(event.target.value)} required><option value="">انتخاب اتصال</option>{availableProxies.map(proxy => <option key={proxy.id} value={proxy.id}>{proxy.label} — {proxy.assigned_device ? `ادامهٔ ${proxy.assigned_device}` : proxy.expected_egress_ip}</option>)}</select></label>{!availableProxies.length && <p className="form-error">ابتدا در بخش «شبکه و پراکسی» یک اتصال آزاد و فعال ثبت کنید، یا «خروجی مستقیم میزبان» را انتخاب کنید.</p>}</> : <p className="field-hint">ترافیک دستگاه با IP خود سرور خارج می‌شود. فضای نام شبکه، درگاه ADB روی loopback و گارد خروجی میزبان همچنان اختصاصی می‌مانند.</p>}<label>برنامهٔ تأییدشده<select value={artifactId} onChange={event => setArtifactId(event.target.value)} required><option value="">انتخاب برنامه</option>{artifacts.map(artifact => <option key={artifact.id} value={artifact.id}>{artifact.label} — {artifact.package}</option>)}</select></label>{!artifacts.length && <p className="form-error">برنامهٔ آمادهٔ نصب وجود ندارد. فایل APK (مثلاً WhatsApp) را از بخش «تنظیمات فارم ← مخزن APK» بارگذاری کنید یا طبق <a href={applicationGuide} target="_blank" rel="noreferrer">بخش ۹ راهنمای واحد</a> با CLI ثبت کنید.</p>}<label className="checkbox-label"><input type="checkbox" checked={authorized} onChange={event => setAuthorized(event.target.checked)} required /><span>مالک شماره هستم یا اجازهٔ استفاده از آن را دارم.</span></label><p className="field-hint">برای ادامهٔ نصب ناتمام، همان شماره، پراکسی و برنامهٔ درخواست اول را وارد کنید؛ میزبان سازگاری درخواست را بررسی می‌کند.</p><div className="notice compact-notice"><LockKeyhole size={18} /><p>درخواست واقعی شامل ساخت داده، راه‌اندازی Android و نصب APK ثبت می‌شود. نتیجه را در صف عملیات دنبال کنید.</p></div>{formError && <p className="form-error" role="alert">{formError}</p>}<div className="form-actions"><button type="button" className="secondary" onClick={() => { setAddOpen(false); setPhone(''); }}>انصراف</button><button className="primary" type="submit" disabled={!canMutate || !authorized || (egress === 'proxy' && !proxyId) || !artifactId}>{pending ? <LoaderCircle size={17} className="spin" /> : <Plus size={17} />}شروع آماده‌سازی</button></div></form></Modal>}

    {proxyOpen && <Modal title="ثبت اتصال پراکسی" onClose={closeProxy}><form className="device-form" autoComplete="off" onSubmit={addProxy}><div className="form-info"><Network size={25} /><div><strong>مسیر خروجی اختصاصی</strong><p>این فرم سرویس پراکسی خریداری‌شده را در فارم ثبت می‌کند.</p></div></div><label>شناسهٔ اتصال<input autoFocus dir="ltr" value={proxyForm.id} onChange={event => setProxyForm({ ...proxyForm, id: event.target.value })} placeholder="proxy-01" maxLength={64} required /></label><label>عنوان<input value={proxyForm.label} onChange={event => setProxyForm({ ...proxyForm, label: event.target.value })} maxLength={80} required /></label><label>نوع<select value={proxyForm.type} onChange={event => setProxyForm({ ...proxyForm, type: event.target.value })}><option value="socks5">SOCKS5</option><option value="http">HTTP CONNECT</option></select></label><div className="form-grid"><label>IPv4 سرویس<input dir="ltr" value={proxyForm.server} onChange={event => setProxyForm({ ...proxyForm, server: event.target.value })} inputMode="decimal" required /></label><label>پورت<input type="number" min="1" max="65535" dir="ltr" value={proxyForm.server_port} onChange={event => setProxyForm({ ...proxyForm, server_port: event.target.value })} required /></label></div><label>نام کاربری<input dir="ltr" value={proxyForm.username} onChange={event => setProxyForm({ ...proxyForm, username: event.target.value })} autoComplete="off" required /></label><label>رمز اتصال<input type="password" dir="ltr" value={proxyForm.password} onChange={event => setProxyForm({ ...proxyForm, password: event.target.value })} autoComplete="new-password" required /></label><label>IPv4 خروجی ثابت مورد انتظار<input dir="ltr" value={proxyForm.expected_egress_ip} onChange={event => setProxyForm({ ...proxyForm, expected_egress_ip: event.target.value })} inputMode="decimal" required /></label><p className="field-hint">IP خروجی را از سرویس‌دهنده بگیرید. پس از ثبت، «تست خروجی» را اجرا کنید. رمز در مرورگر ذخیره نمی‌شود و بعد از ارسال از فرم پاک می‌شود.</p>{formError && <p className="form-error" role="alert">{formError}</p>}<div className="form-actions"><button type="button" className="secondary" onClick={closeProxy}>انصراف</button><button className="primary" type="submit" disabled={!canMutate}>{pending && <LoaderCircle size={16} className="spin" />}ثبت امن اتصال</button></div></form></Modal>}
    {confirm && <Modal title="خاموش‌کردن دستگاه" onClose={() => setConfirm(null)}><div className="confirm-body"><div className="confirm-icon"><Power size={28} /></div><h3>دستگاه <b dir="ltr">{confirm.id}</b> خاموش شود؟</h3><p>جلسهٔ کنترل بسته می‌شود و کانتینرهای دستگاه متوقف می‌شوند. داده‌ها حفظ می‌شوند.</p><div className="form-actions"><button className="secondary" onClick={() => setConfirm(null)}>انصراف</button><button className="danger" disabled={!canMutate} onClick={async () => { if (await perform('down', confirm.id)) setConfirm(null); }}>ثبت درخواست توقف</button></div></div></Modal>}
    {removeDevice && <Modal title="حذف دستگاه از فارم" onClose={closeRemove}><form className="device-form" autoComplete="off" onSubmit={async event => { event.preventDefault(); if (removeConfirm.trim() === removeDevice.id && await perform('remove', removeDevice.id, { confirm: removeDevice.id, purge_data: removePurge })) { closeRemove(); setSelected(null); } }}><div className="confirm-body"><div className="confirm-icon"><Trash2 size={28} /></div><h3>دستگاه <b dir="ltr">{removeDevice.id}</b> از فارم حذف شود؟</h3><p>دستگاه متوقف می‌شود؛ کانتینرها، شبکهٔ اختصاصی و گارد خروجی حذف و پراکسی اختصاص‌یافته آزاد می‌شوند. شناسه از موجودی حذف می‌شود و دوباره استفاده نخواهد شد.</p></div><label>برای تأیید، شناسهٔ دستگاه را بنویسید<input dir="ltr" value={removeConfirm} onChange={event => setRemoveConfirm(event.target.value)} placeholder={removeDevice.id} autoComplete="off" maxLength={8} required /></label><label className="checkbox-label"><input type="checkbox" checked={removePurge} onChange={event => setRemovePurge(event.target.checked)} /><span>دادهٔ پایدار دستگاه (پوشهٔ داده، ولوم، شناسنامهٔ هویت و پروفایل) هم پاک شود.</span></label><p className="field-hint">{removePurge ? 'بدون این داده بازگرداندن دستگاه ممکن نیست؛ اگر لازم است، ابتدا پشتیبان بگیرید.' : 'دادهٔ پایدار روی میزبان می‌ماند و فقط با فرمان میزبان پاک می‌شود.'}</p>{formError && <p className="form-error" role="alert">{formError}</p>}<div className="form-actions"><button type="button" className="secondary" onClick={closeRemove}>انصراف</button><button className="danger" disabled={!canChangeDevice || removeConfirm.trim() !== removeDevice.id}>{pending ? <LoaderCircle size={17} className="spin" /> : <Trash2 size={17} />}حذف دستگاه</button></div></form></Modal>}
    {jobDetails && <Modal title="جزئیات عملیات" onClose={() => setSelectedJob(null)}><div className="detail-body"><dl className="detail-list"><div><dt>عملیات</dt><dd>{actionText[jobDetails.action] ?? jobDetails.action}</dd></div><div><dt>وضعیت</dt><dd>{jobStateText[jobDetails.state]}</dd></div><div><dt>دستگاه</dt><dd dir="ltr">{jobDetails.device ?? '—'}</dd></div><div><dt>شناسه</dt><dd dir="ltr" className="job-id">{jobDetails.id}</dd></div><div><dt>آخرین تغییر</dt><dd>{formatTime(jobDetails.updated_at)}</dd></div></dl>{jobDetails.error && <p className="form-error" role="alert">{jobDetails.error}</p>}{jobDetails.result && <><h3>نتیجهٔ ثبت‌شدهٔ سرور</h3><pre className="job-result" dir="ltr">{JSON.stringify(jobDetails.result, null, 2)}</pre></>}</div></Modal>}
    {help && <Modal title="راهنمای عملیات زنده" onClose={() => setHelp(false)}><div className="detail-body"><ol className="help-steps"><li><b>اتصال میزبان را بررسی کنید</b><p>نشان وضعیت زنده و زمان آخرین گزارش باید تازه باشند. هنگام قطع ارتباط، فرمان‌های تغییر غیرفعال‌اند.</p></li><li><b>پراکسی و برنامه را آماده کنید</b><p>اتصال اختصاصی را ثبت و تست کنید. برنامهٔ نصب از فهرست تأییدشدهٔ میزبان انتخاب می‌شود.</p></li><li><b>دستگاه را بسازید یا روشن کنید</b><p>نتیجهٔ واقعی در «جلسات و صف» ثبت می‌شود؛ خطای اجرا با جزئیات قابل مشاهده است.</p></li><li><b>کنترل زنده را باز کنید</b><p>پس از سلامت سرویس صفحه، تصویر scrcpy داخل کنسول یا در مسیر مستقل دستگاه باز می‌شود.</p></li><li><b>خاموش و پشتیبان‌گیری کنید</b><p>پس از ثبت موفق توقف، بکاپ را اجرا کنید و وجود آرشیو را در بخش پشتیبان‌ها ببینید.</p></li></ol><a className="secondary inline" href={guide} target="_blank" rel="noreferrer"><BookOpen size={17} />راهنمای واحد پلتفرم</a></div></Modal>}
    {toast && <div className="toast" role="status"><Activity size={18} /><span>{toast}</span><button aria-label="بستن پیام" onClick={() => setToast('')}><X size={16} /></button></div>}
  </div>;
}

function SearchField({ query, onChange }: { query: string; onChange: (value: string) => void }) { return <div className="search-field"><Search size={17} /><input aria-label="جست‌وجوی دستگاه" value={query} onChange={event => onChange(event.target.value)} placeholder="شناسه، شمارهٔ پوشیده یا پراکسی…" />{query && <button aria-label="پاک‌کردن جست‌وجو" onClick={() => onChange('')}><X size={14} /></button>}</div>; }
function Stat({ icon, label, value, note }: { icon: ReactNode; label: string; value: string; note: string }) { return <div className="stat-card"><div className="stat-top"><span>{label}</span>{icon}</div><div className="stat-number">{value}</div><p>{note}</p></div>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty"><div><Box size={29} strokeWidth={1.4} /></div><h3>{title}</h3><p>{text}</p></div>; }
function Setting({ title, note, value }: { title: string; note: string; value: string }) { return <div className="setting-row"><div><h3>{title}</h3><p>{note}</p></div><span className="tag setting-value">{value}</span></div>; }
function ProxyHealth({ proxy }: { proxy: ProxyRecord }) { return proxy.last_health ? <span className={`status ${proxy.last_health.status === 'healthy' ? 'running' : 'error'}`}><i />{proxy.last_health.status === 'healthy' ? 'آخرین تست موفق' : 'آخرین تست ناموفق'}<small dir="ltr">{proxy.last_health.observed_egress_ip ?? '—'}</small></span> : <span className="status unknown">آزمایش نشده</span>; }
function JobList({ jobs, onOpen, onCancel, canMutate, unavailable = false }: { jobs: Job[]; onOpen: (job: Job) => void; onCancel: (job: Job) => void; canMutate: boolean; unavailable?: boolean }) {
  return jobs.length ? <div className="job-list">{jobs.map(job => <div className="job-row" key={job.id}><span className={`job-indicator ${job.state}`}>{job.state === 'running' ? <LoaderCircle size={18} className="spin" /> : <Clock3 size={18} />}</span><div className="job-main"><button className="text-button" onClick={() => onOpen(job)}>{actionText[job.action] ?? job.action}{job.device && <span dir="ltr">{job.device}</span>}</button><p>{formatTime(job.updated_at)}</p>{job.error && <p className="job-error">{job.error}</p>}</div><span className={`job-state ${job.state}`}>{jobStateText[job.state]}</span>{job.state === 'queued' && <button className="secondary small" disabled={!canMutate} onClick={() => onCancel(job)}>لغو</button>}<IconButton label="جزئیات عملیات" onClick={() => onOpen(job)}><ArrowUpLeft size={17} /></IconButton></div>)}</div> : <Empty title={unavailable ? 'تاریخچهٔ عملیات در دسترس نیست' : 'درخواستی در این فهرست نیست'} text={unavailable ? 'تا دریافت پاسخ معتبر، نمی‌توان خالی‌بودن صف یا تاریخچه را تأیید کرد.' : 'فقط عملیات ثبت‌شده در سرویس کنترل نمایش داده می‌شوند.'} />;
}
// رویدادهای پایدار میزبان (روشن/خاموش، کرش، بازیابی، توقف حفاظتی) که با هر snapshot به‌روز می‌شوند.
function EventList({ events }: { events: FarmEvent[] }) {
  if (!events.length) return <Empty title="رویدادی ثبت نشده است" text="روشن‌شدن، کرش، بازیابی خودکار و توقف حفاظتی دستگاه‌ها این‌جا ثبت می‌شوند." />;
  return <div className="job-list">{events.map((event, index) => <div className="job-row" key={`${event.at}-${index}`}>
    <span className={`job-indicator ${event.kind.includes('failed') || event.kind.includes('crashed') || event.kind.includes('held') ? 'failed' : event.kind.includes('recovery') ? 'running' : 'succeeded'}`}><Activity size={18} /></span>
    <div className="job-main"><p><b>{eventText[event.kind] ?? event.kind}</b>{event.device && <span dir="ltr"> {event.device}</span>}</p><p>{formatTime(event.at)}{event.detail ? ` · ${event.detail}` : ''}</p></div>
  </div>)}</div>;
}
